PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,state TEXT NOT NULL DEFAULT 'IDLE',pending TEXT,temp_image TEXT, snapshot TEXT,next_number INTEGER NOT NULL DEFAULT 9);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id TEXT NOT NULL,piece_number INTEGER NOT NULL,title TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),image_url TEXT NOT NULL,sold INTEGER NOT NULL DEFAULT 0,UNIQUE(session_id,piece_number));
